import re


def slug(text):
    """Return a lowercase ASCII slug: letters and digits kept, other runs
    collapsed to a single hyphen, leading/trailing hyphens removed."""
    slug_text = re.sub(r"[^a-z0-9]+", "-", text.lower())
    return slug_text.strip("-")

